SELECT CASE WHEN o.amount >= 1460 THEN 'high' WHEN o.amount >= 540 THEN 'mid' ELSE 'low' END AS amount_bucket, MAX(oi.unit_price) AS max_unit_price FROM order_items oi INNER JOIN orders o ON oi.order_id = o.id LEFT OUTER JOIN customers c ON o.customer_id = c.id WHERE UPPER(TRIM(c.email)) = 'EMMA@OUTLOOK.COM' GROUP BY CASE WHEN o.amount >= 1460 THEN 'high' WHEN o.amount >= 540 THEN 'mid' ELSE 'low' END ORDER BY max_unit_price;
